<template>
  <Alert v-if="items.length" variant="destructive">
    <TriangleAlert class="size-5" />
    <AlertTitle>Incomplete project onboarding</AlertTitle>
    <AlertDescription>This {{ roleLabel }} is missing the following project onboarding steps.</AlertDescription>
    <div class="mt-3 flex flex-wrap gap-2">
      <Badge v-for="item in items" :key="item.checkmark" variant="destructive" size="md" class="normal-case">
        {{ item.label }}
      </Badge>
    </div>
  </Alert>
</template>

<script setup lang="ts">
import { TriangleAlert } from 'lucide-vue-next';
import type { ProjectOnboardingState, UserRole } from '~/client';
import { getUserRole } from '~/constants/users/userRoles';

interface Props {
  projectOnboardingState: ProjectOnboardingState;
  userRole: UserRole;
}

const props = defineProps<Props>();

const items = computed(() => getIncompleteProjectOnboardingFlags(props.projectOnboardingState));
const roleLabel = computed(() => getUserRole(props.userRole).name.toLowerCase());
</script>
