<template>
  <section class="flex flex-col gap-4">
    <AppLoader v-if="isLoading" variant="inline" subject="assignment" class="!py-0" />
    <AppError
      v-else-if="error"
      title="Failed to load assignment"
      :error="error"
      :action="refetch"
      action-text="Retry"
    />
    <template v-else-if="assignment">
      <PageTitle :title="`${userName || 'Assignment'}`" :subtitle="projectName" show-doc>
        <template #title>
          <span class="flex flex-row items-center gap-2">
            {{ userName || 'Assignment' }}
            <Badge
              v-if="assignment.assignment_status"
              class="text-base font-normal"
              :variant="getAssignmentStatus(assignment.assignment_status).variant"
            >
              {{ getAssignmentStatus(assignment.assignment_status).name }}
            </Badge>
          </span>
        </template>
        <FilterTabsNav :items="navigationItems" rounded />
      </PageTitle>
    </template>

    <AssignmentsDetailsProjectOnboardingAlert
      v-if="assignment?.project_onboarding_state && !isLoading && !error"
      :project-onboarding-state="assignment.project_onboarding_state"
      :user-role="assignment.user_role"
    />

    <AssignmentsDetailsOnboardingAlert
      v-if="assignment?.onboarding_state && !isLoading && !error"
      :onboarding-state="assignment.onboarding_state"
      :user-role="assignment.user_role"
    />

    <GoBackButton
      v-if="!isLoading && !error"
      subject="assignments"
      :fallback-to="{ name: 'projects-id-assignments', params: { id: projectId } }"
    />

    <AssignmentsDetailsStaffAlert
      v-if="assignment && (assignment.user_role === 'manager' || assignment.user_role === 'admin')"
      :role="assignment.user_role"
    />

    <NuxtPage v-if="!isLoading && !error" :assignment="assignment" :refetch="refetch" />
  </section>
</template>

<script setup lang="ts">
import { getAssignmentDetails, getUserShortInfo, getProjectShortInfo } from '~/client';
import { getAssignmentStatus } from '~/constants/assignments/assignmentStatusConfig';
import type { NavigationItem } from '~/types/projects';

definePageMeta({
  roles: ['admin', 'manager'],
});

const projectId = computed(() => useRoute('assignments-project_id-user_id').params.project_id?.toString() || '');
const userId = computed(() => useRoute('assignments-project_id-user_id').params.user_id?.toString() || '');
const currentRouteName = computed(() => useRoute().name);

const {
  data: assignment,
  error,
  isLoading,
  refetch,
} = useQuery({
  key: () => ['assignment.details', `${projectId.value}:${userId.value}`],
  query: () =>
    getAssignmentDetails({
      composable: '$fetch',
      path: { project_id: projectId.value, user_id: userId.value },
    }),
  enabled: () => !!projectId.value && !!userId.value,
});

const { data: userShort } = useQuery({
  key: () => ['user.short-info', userId.value],
  query: () => getUserShortInfo({ composable: '$fetch', path: { user_id: userId.value } }),
  enabled: () => !!userId.value,
});

const { data: projectShort } = useQuery({
  key: () => ['project.short-info', projectId.value],
  query: () => getProjectShortInfo({ composable: '$fetch', path: { project_id: projectId.value } }),
  enabled: () => !!projectId.value,
});

const userName = computed(() => (userShort.value ? username(userShort.value) : undefined));
const projectName = computed(() => projectShort.value?.name);

const navigationItems = computed<NavigationItem[]>(() => [
  {
    label: 'Overview',
    to: { name: 'assignments-project_id-user_id', params: { project_id: projectId.value, user_id: userId.value } },
    selected: currentRouteName.value === 'assignments-project_id-user_id',
  },
  {
    label: 'Status History',
    to: {
      name: 'assignments-project_id-user_id-status-history',
      params: { project_id: projectId.value, user_id: userId.value },
    },
    selected: currentRouteName.value === 'assignments-project_id-user_id-status-history',
  },
]);

useHead({
  title: computed(() =>
    userName.value && projectName.value ? `${userName.value} · ${projectName.value}` : 'Assignment'
  ),
});
</script>
