<template>
  <Alert v-if="items.length" variant="warning">
    <TriangleAlert class="size-5" />
    <AlertTitle>Incomplete onboarding</AlertTitle>
    <AlertDescription>This {{ roleLabel }} hasn't completed the following steps.</AlertDescription>
    <div class="mt-3 flex flex-wrap gap-2">
      <Badge v-for="item in items" :key="item.checkmark" variant="warning" size="md" class="normal-case">
        {{ item.label }}
      </Badge>
    </div>
  </Alert>
</template>

<script setup lang="ts">
import { TriangleAlert } from 'lucide-vue-next';
import type { OnboardingState, UserRole } from '~/client';
import { getUserRole } from '~/constants/users/userRoles';

interface Props {
  onboardingState: OnboardingState;
  userRole: UserRole;
}

const props = defineProps<Props>();

const items = computed(() => getIncompleteOnboardingFlags(props.onboardingState));
const roleLabel = computed(() => getUserRole(props.userRole).name.toLowerCase());
</script>
